android.extraProguardRules:
# expo-camera finds ML Kit with Class.forName(), which the shrinker cannot see.
# Without these, release builds lose the barcode reader and QR codes never scan.
-keep class com.google.mlkit.** { *; }
-keep class com.google.android.gms.internal.mlkit_vision_barcode** { *; }
-keep class com.google.android.gms.vision.** { *; }
-keep class com.google.android.gms.common.moduleinstall.** { *; }
-keep class com.google.android.gms.code.scanner.** { *; }
-keep class androidx.camera.mlkit.** { *; }
-keep class expo.modules.camera.** { *; }
-dontwarn com.google.mlkit.**
